import React, { useState } from 'react';
import { useParams } from 'react-router-dom';
import { excursions } from '../../Data/excursions';
import './ExcursionPage.css';

const ExcursionPage = () => {
  const { id } = useParams();
  const [isFavorite, setIsFavorite] = useState(false);
  const [inCart, setInCart] = useState(false);

  const handleToggleFavorite = () => {
  setIsFavorite(prev => !prev);
};

const handleToggleCart = () => {
  setInCart(prev => !prev);
};

  // приводим id из URL к числу
  const excursion = excursions.find(
    (item) => item.id === Number(id)
  );

  // защита, если id не найден
  if (!excursion) {
    return (
      <div className="excursion-page">
        <h2>Экскурсия не найдена</h2>
      </div>
    );
  }

  return (
    <div className="excursion-page">
    {/* TITLE */}
    <h1 className="excursion-page__title">
        {excursion.title}
    </h1>

    {/* MAIN BLOCK */}
    <div className="excursion-page__main">
        {/* IMAGE */}
        <div className="excursion-page__image">
        <img src={excursion.image} alt={excursion.title} />

        <button
            className="excursion-page__favorite"
            title="Добавить в избранное"
        >
            <img
            src={
              isFavorite
                ? '/assets/icons/heart2.svg'
                : '/assets/icons/like.svg'
            }
            alt="Избранное"
          />
        </button>
        </div>

        {/* INFO */}
        <div className="excursion-page__info-block">
        <div className="excursion-page__location">
            {excursion.country}, {excursion.city}
        </div>

        <div className="excursion-page__info">
            <span className="excursion-page__price">
            {excursion.price.toLocaleString()} ₽
            </span>
            <span className="excursion-page__rating">
            ★ {excursion.rating}
            </span>
        </div>

        <div className="excursion-page__dates">
            <div>Дата начала: 12.06.2025</div>
            <div>Дата окончания: 15.06.2025</div>
        </div>

        <button className="excursion-page__add-btn">
            В корзину
        </button>
        </div>
    </div>

    {/* DESCRIPTION */}
    <div className="excursion-page__description">
        {excursion.description}
    </div>

    {/* REVIEWS */}
    <section className="excursion-page__reviews">
        <h2>Отзывы</h2>
        <p className="reviews-placeholder">
        Отзывы появятся позже
        </p>
    </section>
</div>
  );
};

export default ExcursionPage;
